start=s.index('const NAMED={')
end=s.index('const UNLOCK_GROUPS=',start)
head,block,tail=s[:start],s[start:end],s[end:]
for old,new in mapping.items():
    count=block.count(old)
    if count!=1:
        raise SystemExit(f'expected exactly one card description match ({count}): {old}')
    block=block.replace(old,new,1)
s=head+block+tail

old='- [ ] 카드 효과 문체 통일'
new='- [x] 카드 효과 문체 통일 — 사용자 노출 네임드 효과문을 `조건 → 효과` 서술형으로 통일. 의무 효과는 `~한다/얻는다/뽑는다/증가한다`, 선택 효과는 `~할 수 있다`를 사용하고 `+N`, `보호막 N.`, `1장 뽑기.` 같은 단독 축약형과 `폭발를/세트을/세트과` 조사 오류를 제거'
if old not in r: raise SystemExit('ROADMAP style anchor missing')
r=r.replace(old,new,1)

old_terms='''사용자 노출 카드 효과는 다음 형태를 우선한다.\n- `~하면, ~한다.`\n- `~했을 때, ~한다.`\n- `카드 1장을 뽑는다.`\n- `보호막 12를 얻는다.`\n- `스위치를 상대에게 넘긴다.`\n- `누적 위력 +10.`'''
new_terms='''사용자 노출 카드 효과는 **조건 → 효과** 순서의 서술형을 우선한다.\n- 의무적으로 처리하는 효과는 `~한다.`, `~얻는다.`, `~뽑는다.`, `~증가한다.`처럼 문장을 끝낸다.\n- 플레이어가 선택할 수 있는 효과만 `~할 수 있다.`를 사용한다.\n- 수치는 명사만 남기는 축약형보다 `보호막 12를 얻는다.`, `누적 위력이 10 증가한다.`처럼 무엇이 변하는지 적는다.\n- `카드 1장을 뽑는다.`처럼 대상과 수량을 가능한 한 함께 적는다.\n- `턴당 1회.`처럼 단독 제한 문구를 두기보다 `턴당 1회만 발동한다.`처럼 문장으로 적는다.\n- 여러 효과는 `~하고`, `~한 뒤`, `~라면`으로 해결 순서를 드러낸다.'''
if old_terms not in t: raise SystemExit('card text style guide anchor missing')
t=t.replace(old_terms,new_terms,1)

index.write_text(s)
road.write_text(r)
terms.write_text(t)
print('normalized descriptions',len(mapping))
